WITH cleaned AS (SELECT *, FLOOR(revenue) AS revenue_whole, DATE_FORMAT(sale_date, 'MMM yyyy') AS sale_date_label FROM store_sales WHERE sale_date >= TO_DATE('2023-06-28')) SELECT dim.city, dim.region, COUNT(*) AS num_rows, MAX(a.units) AS max_units, ROUND(SUM(a.revenue_whole), 2) AS total_revenue_whole, GROUPING_ID() AS gid FROM cleaned a LEFT JOIN stores dim ON a.store_id = dim.id GROUP BY GROUPING SETS ((dim.city, dim.region), (dim.city), ())
